js='''(()=>{const widths={'4x3':1920,'16x10':2304,'16x9':2560,'21x9':3360,'32x9':5120},q=id=>document.getElementById('score-'+id);function wipe(){q('wipe-draft').style.clipPath='inset(0 0 0 '+q('wipe-input').value+'%)';}function texture(){q('texture-ref').src='hiscores-v1/hiscores-'+q('ref').value+'.png';}function update(){const center=q('framing').value==='center',ratio=center?'4x3':q('aspect').value,w=widths[ratio],base='hiscores-v1/hiscores-'+ratio,orig=base+'-original.png',draft=base+'-draft.png';q('aspect').disabled=center;for(const id of ['original','wipe-original'])q(id).src=orig;for(const id of ['draft','wipe-draft'])q(id).src=draft;q('original-link').href=orig;q('draft-link').href=draft;const pct=1920/w*100;for(const e of document.querySelectorAll('.score-safe'))Object.assign(e.style,{width:pct+'%',left:(100-pct)/2+'%'});q('comparison').dataset.mode=q('view').value;q('wipe-controls').hidden=q('view').value!=='wipe';q('caption').textContent='High Scores · '+ratio.replace('x',':')+' · '+w+'×1440 · '+(center?'matching original center':'centered board and widened scenery')+' · unapproved artwork · game validation pending';wipe();}for(const id of ['aspect','view','framing'])q(id).onchange=update;q('wipe-input').oninput=wipe;q('ref').onchange=texture;q('bounds').onclick=()=>{const show=q('bounds').getAttribute('aria-pressed')!=='true';q('bounds').setAttribute('aria-pressed',String(show));for(const e of document.querySelectorAll('.score-frame'))e.classList.toggle('show',show);};texture();update();})();''';s+='<script>'+js+'</script>\n';(p.parent/'review.html').write_text(s);print('High Scores firstpanel;5ratios/original/wipe/center/bounds/joins/source refs;Rewards approvalretained')
